namespace Biertan.UI
{
    /// <summary>Every creature, master and person met on the road, with the folklore and history behind them.
    /// Port of bestiary.gd.</summary>
    public static class BestiaryData
    {
        public readonly struct Entry
        {
            public readonly string name, ro, kind, img, lore, tip;
            public Entry(string name, string ro, string kind, string img, string lore, string tip)
            { this.name = name; this.ro = ro; this.kind = kind; this.img = img; this.lore = lore; this.tip = tip; }
        }

        public static readonly Entry[] Entries =
        {
            new("Wolf", "Lupul", "Creature", "wolf_idle",
                "Carpathian wolves were the shepherd's oldest enemy. Romanian folk calendar keeps a day for them: on the night of Saint Andrew (30 November), the patron of wolves, they are said to roam freely and even to speak, and households rub garlic on doors and windows against them and the strigoi alike.",
                "Fast but fragile. Strike as they close in, and dodge through the pack instead of backing away."),
            new("Pricolici", "Pricoliciul", "Creature", "wolf_run",
                "The true Romanian werewolf. A pricolici is the restless dead, often a wicked man, who comes back from the grave as a great wolf or dog to prey on the living. Some tales say living men can turn into one at night.",
                "When it crouches and glows red it is about to lunge. Dodge sideways, then punish it."),
            new("Waking scarecrow", "Sperietoarea", "Creature", "scarecrow_awake",
                "Straw figures had real ritual work in Romanian villages: in the Caloian rain rite, a clay or straw effigy was mourned and buried to bring the rain. In this tale, the effigies left in the Wolf Forest have been taken by restless spirits.",
                "Slow and tough. It only wakes when you come close, so you can choose the moment."),
            new("Shade of the taken", "Umbra", "Creature", "shade_a",
                "An old rule of the night: never answer the first time a voice calls your name in the dark. Strigoi, Iele and other spirits were believed to call people by name to lure them out. The shades are what comes when you answer.",
                "Weak but persistent. In the Wolf Forest, do not walk toward the voice."),
            new("Iele", "Ielele (Dânsele, Frumoasele)", "Creature", "iele_a",
                "Fairy women of the air who dance the hora at night in forest clearings and meadows. Where they dance the grass is scorched in a ring. Whoever watches them, sleeps where they danced or works on their holy days (above all at Rusalii) may be struck lame or mad. People avoid saying their name, calling them 'the Beautiful Ones' or 'the Dancers', and wear wormwood (pelin) and garlic for protection.",
                "Their song slows you and draws you in. Wormwood from Katharina makes you deaf to it. Salt sends them fleeing."),
            new("Moroi", "Moroiul", "Creature", "moroi_awake",
                "In Romanian folk belief the moroi is a restless dead soul, often of a child who died unbaptized, that returns to drain the life of the living. In this tale they are the miners left in the salt, which kept their bodies from rotting.",
                "They rise when you get close. Salt burns them twice as hard as other dead."),
            new("Strigoi", "Strigoiul", "Creature", "strigoi_stand",
                "The central figure of Romanian vampire belief. Strigoi morți are the dead who rise from the grave to drain their family, livestock and village; strigoi vii are living people, born with a caul or a tail, whose souls roam at night. Garlic, incense, a stake or a needle through the heart, and watchfulness on Saint Andrew's and Saint George's nights were the defences.",
                "A red ring marks where it will land when it leaps. Its bites heal it unless you wear Veta's garlic wreath."),
            new("Bats", "Liliecii", "Creature", "bat_a",
                "Romanian tales let strigoi take animal shapes at night, more often cats, dogs, moths or frogs than bats. The bat of the vampire is the later gift of Western novels; in this tale they serve as Vlad's messengers.",
                "Erratic and quick. A single strike kills them; don't chase, let them come to you."),
            new("Blood ward", "Strajă de sânge", "Creature", "",
                "An invention of this tale: a stone that Vlad's blood keeps alive, sealing each gate of Biertan's three walls. It is a dark mirror of the church's real defences, the nineteen-lock sacristy door and the three rings of stone.",
                "It spawns bats while you are near. Break it quickly and the gate rises."),
            new("Fire skull", "Țeasta de foc", "Creature", "",
                "Burning skulls breathed out by the Balaur's fire head. Folk tales give dragons fire, smoke and poison; the hunting skulls are this tale's own invention.",
                "They home in slowly. Cut them down or dodge so they burst behind you."),
            new("The Vârcolac", "Vârcolacul", "Master", "boss_idle",
                "Not the werewolf of films. In Romanian folklore the vârcolac is a creature like a lean dog or wolf, sometimes counted with the dragons, 'born of the air': from unbaptized children, from sinners, or from thread that women spin at night without a candle. It climbs those threads to the sky and bites the moon and the sun; an eclipse is the vârcolac eating, a red moon is the moon's blood. When it gorges, it grows heavy, the threads snap and it falls. Villagers rang church bells, beat pots and fired guns to scare it off.",
                "In the dark it rides its threads and only a fire near it makes it solid. Let it swallow the flames: three, and its threads snap."),
            new("Muma Pădurii", "Muma Pădurii (Mama Pădurii)", "Master", "muma_idle",
                "The Mother of the Forest: an ancient, ugly hag of the deep woods, sometimes part tree herself, who leads travellers astray and steals or torments children; mothers blamed her for babies who cried all night. In some regions she is also the forest's guardian, punishing those who harm it.",
                "Salt burns away her bark and reveals the real sister among the three. Every hit adds to your madness; tinctures heal you but not your mind."),
            new("The Balaur", "Balaurul", "Master", "balaur_body",
                "The many-headed serpent dragon of Romanian fairy tales, with three, seven or twelve heads that grow back when cut, guardian of springs, treasures and stolen princesses, slain by Făt-Frumos. This one carries powers from Ion Creangă's tale of Harap-Alb: Gerilă's frost, the Red Emperor's red-hot copper house, Setilă's thirst that drinks lakes dry, and the jewelled head of the enchanted stag.",
                "Cut a head, then sear the stump with the founder's torch before it regrows. Hide behind stone from the stag's gaze, and leave the marked lane when it rears to devour."),
            new("The Bear of the Garden", "Ursul din Grădina Ursului", "Master", "bear_stand",
                "In Ion Creangă's tale of Harap-Alb, the treacherous Spân sends the hero to bring lettuce from the Bear's Garden, which no one had ever entered and come back from. Saint Sunday helps him by putting the bear to sleep with a sleeping drink. Bears were also honoured in the folk calendar: on Bear's Day (2 February) the bear leaves its den to look at the weather, and the winter bear dance (jocul ursului) still goes through Moldavian villages at New Year.",
                "Optional, hidden in the south-east of the Hollow Hills. Watch for the red line before a charge, run out of the ring when it rears up, and never fight it inside a beehive swarm."),
            new("Strigoi Vlad", "Strigoiul Vlad", "Master", "vlad_idle",
                "An invented lord of the dead, a boyar's son from over the mountains who rose three winters after his burial. He is a strigoi mort of the old belief, not the Dracula of Bram Stoker's novel, and he has no link to the historical prince Vlad III. Like the vârcolac, he fears the sound of church bells.",
                "Stand in salt during the Nihil rite. Ring the great bell to drag him out of mist. Too many of his hits make you a vampire: then tinctures burn, but your strikes drink."),
            new("Frau Anna Roth", "Innkeeper of Saschiz", "Person", "npc_anna",
                "The Transylvanian Saxons, German settlers invited by the Hungarian kings from the 12th century onwards, built hundreds of villages around fortified churches. Inns like Anna's stood on the trade roads between their towns.",
                "Sells garlic tinctures."),
            new("Master Hans", "Blacksmith of Saschiz", "Person", "npc_hans",
                "Saxon guilds of smiths, potters and weavers were famous across the region; Saschiz itself was known for its blue-glazed pottery.",
                "Whets your blade for twenty-five coins."),
            new("Old Ileana", "Herbalist of Saschiz", "Person", "npc_ileana",
                "A red thread tied at the wrist is an old Romanian protection against the evil eye (deochi). Wise women like Ileana knew charms (descântece), herbs and the rules the dead must keep.",
                "Her red thread charm raises your health."),
            new("Gheorghe", "Shepherd", "Person", "npc_gheorghe",
                "Romanian shepherds drove their flocks between mountain pastures and lowlands (transhumance), living with wolves, the weather and the old beliefs. The ballad Miorița, about a shepherd and his ewe, is among the best-loved Romanian folk poems.",
                "Find his three lost ewes in the Wolf Forest."),
            new("Pafnutie", "Hermit (sihastru)", "Person", "npc_hermit",
                "Hermits (sihaștri) living alone in forest cells and caves are a long Orthodox tradition in the Carpathians. Folk belief held that treasures buried by haiducs, the outlaws of the old roads, burn with a blue flame on certain nights.",
                "Drink from his spring. Wait for midnight in the Wolf Forest and look for blue fire."),
            new("Pfarrer Lukas", "Pastor of Richiș", "Person", "npc_pastor",
                "The Transylvanian Saxons became Lutheran in the 16th century, and their pastors led village life from the fortified church. Richiș's church is known for its carved Green Men.",
                "Gives the quest of the singing children."),
            new("Vasile", "Salt miner", "Person", "npc_vasile",
                "Transylvania sits on enormous salt deposits, mined since Roman times at places like Turda and Praid. Salt is also a folk protection against the unclean dead.",
                "Gives the salt pouch and sells salt."),
            new("Katharina", "Herbalist of Richiș", "Person", "npc_katharina",
                "Wormwood (pelin) and garlic were carried against the Iele, above all in the week of Rusalii. Saxon women's festive dress with its tall black headdress is still worn on feast days in some villages.",
                "Sells the wormwood sprig against the Iele's song."),
            new("Rozalia", "Mother of Richiș", "Person", "npc_rozalia",
                "Her embroidered blouse is the ie, the traditional Romanian shirt whose patterns differ from village to village.",
                "Thanks you with tinctures once the children are home."),
            new("Meister Konrad", "Bell-founder of Moșna", "Person", "npc_konrad",
                "Church bells rang out more than the hours: in folk belief their sound drove away storms, vârcolaci and the unclean dead. A silenced bell was a village without protection.",
                "Gives the founder's torch; sharpens your blade."),
            new("Hannes", "Keeper of the bacon tower", "Person", "npc_hannes",
                "Saxon villages kept each family's smoked bacon in a tower of the fortified church, safe for a siege. On set days each household came to cut its portion.",
                "Sells ham and plum brandy (heals like a tincture)."),
            new("Magda", "The impatient one of Moșna", "Person", "npc_magda",
                "Every village has one. 'Haida!' (also haide, hai) is the Romanian 'come on, let's go!', a word borrowed through Turkish 'haydi' and shouted across the Balkans at slow oxen, slow children and slow heroes alike.",
                "Cannot be pleased. Do not try."),
            new("Veta", "Cantor's widow", "Person", "npc_veta",
                "Garlic is the great protection against strigoi in Romanian belief, hung at doors and windows and rubbed on the cattle on the nights of Saint Andrew and Saint George.",
                "Sells the garlic wreath: strigoi bite softer and cannot drink."),
            new("Martin", "Sexton of Biertan", "Person", "npc_sexton",
                "Biertan's sacristy door has a lock with nineteen bolts, made in the early 16th century, which won a prize at the 1900 Paris World Exhibition. Biertan was the seat of the Lutheran bishops of Transylvania from 1572 to 1867.",
                "Gives the church key and supplies before the climb."),
            new("Andreas and Sofia", "Prisoners of the marriage prison", "Person", "npc_sofia",
                "Biertan's 'marriage prison' is real: couples who wanted to divorce were locked in a small house in the fortress with one bed, one table, one plate and one spoon. Local tradition claims that in centuries of use only one couple went on to divorce.",
                "Sofia's red wedding ribbon raises your health."),
            new("Via Transilvanica", "Drumul care unește", "Trail", "",
                "A long-distance trail of about 1,400 km across Romania, from Putna in Bukovina to Drobeta-Turnu Severin on the Danube, marked along the way by carved stone milestones. Its Terra Saxonum section walks through the Saxon villages of this tale, Saschiz and Biertan among them.",
                "Do you want to hunt the creatures of Biertan yourself? Plan your hunt and check the route on viatransilvanica.com (tap the banner above)."),
        };
    }
}
